  s.parts.forEach(p=>{p.notes=withStarts(p.notes)});
  s.notes=s.parts.flatMap((p,pi)=>p.notes.filter(n=>!n.rest).map(n=>Object.assign({},n,{part:pi}))).sort((a,b)=>a.start-b.start||a.part-b.part);
