      const key=up+oct;let alt;if(acc){alt=acc==='='?0:(acc.match(/\^/g)||[]).length-(acc.match(/_/g)||[]).length;v.bar[key]=alt}else alt=v.bar[key]!=null?v.bar[key]:(keyAcc[up]||0);
