  const mask=document.createElement('canvas');mask.width=r.W;mask.height=r.H;const mc=mask.getContext('2d'),diag=Math.hypot(r.W,r.H);
  const disc=(x,y,R)=>{const g=mc.createRadialGradient(x,y,R*.55,x,y,R);g.addColorStop(0,'rgba(0,0,0,1)');g.addColorStop(1,'rgba(0,0,0,0)');mc.fillStyle=g;mc.fillRect(0,0,r.W,r.H)};
