  if(scroll)$('#behold').scrollIntoView({behavior:REDUCED?'auto':'smooth',block:'start'});
  await new Promise(r=>setTimeout(r,60));
  const ended=song.stream&&song.streamEnded;
  const live=!still&&!ended&&(song.rec||stageLive||$('#liveToggle').checked);
  if(song.rec&&!live&&!(song.chroma&&song.chroma.some(v=>v>0))){btn.disabled=false;$('#repaint').disabled=false;if(!still)toast(ended?'That live session has ended. Start listening again.':'Play the recording first.');return}
  let seed=Math.floor(Math.random()*99999)+1,params={},title,by,stmt=null;const shared=shareSeed;shareSeed=null;if(shared){seed=shared.seed;params=shared.params}
