$('#stageBtn').onclick=openStage;$('#stageBtn2').onclick=openStage;
$('#stClose').onclick=closeStage;
$('#stArr').addEventListener('change',()=>setArrStyle($('#stArr').value));
// playing a song shows it: the sheet music and the painting side by side, with the painter at work
function playAndPaint(){if(playing&&!playing.stopped){playing.stop();return}if(!song)return;clearTimeout(zen.t);stage.classList.remove('between');if($('#stage').hidden)openStage();$('#stEmpty').hidden=true;stageLive=true;paint(false).finally(()=>{stageLive=false})}
// a change of arrangement, tempo or instrument mid-song starts it again the same way it was playing
function restartPlay(){if(playing&&playing.live){playing.stop();playAndPaint()}else togglePlay(song,true)}
$('#stPlay').onclick=playAndPaint;
$('#stFull').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await stage.requestFullscreen()}catch(e){toast('Full screen is not available in this view.')}};
document.addEventListener('fullscreenchange',()=>{$('#stFull').textContent=document.fullscreenElement?'Leave full screen':'Full screen'});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!stage.hidden&&!document.fullscreenElement)closeStage()});
let stageRT=0;window.addEventListener('resize',()=>{if(stage.hidden)return;clearTimeout(stageRT);stageRT=setTimeout(renderStage,200)});
/* ---------- zen mode: calm pieces one after another, each painting a new picture, with only a breathing guide on screen ---------- */
const zen={on:false,list:[],at:-1,pics:[],pi:-1,t:0,idleT:0,breath:true};
