['pointermove','pointerdown','keydown'].forEach(t=>stage.addEventListener(t,zenWake,{passive:true}));
$('#zenBtn').onclick=zenStart;$('#stZen').onclick=zenStart;
$('#zenPlay').onclick=()=>{if(playing&&!playing.stopped){clearTimeout(zen.t);playing.stop()}else if(stage.classList.contains('between'))zenNext();else{$('#zenNow').innerHTML=`<b>${esc(song.title)}</b>${esc(song.by)}`;playAndPaint()}};
