$('#zenFull').onclick=()=>$('#stFull').click();
$('#zenLeave').onclick=closeStage;
document.addEventListener('keydown',e=>{if(!zen.on||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='n'||e.key==='N'){e.preventDefault();zenNext()}});
// the Stop/Play label follows what is sounding
