function posterName(ext){return'fude-'+($('#artTitle').textContent||'painting').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)+ext}
async function saveBlob(blob,name){
  if(!downloads){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000);toast('Saved');return}
  try{await downloads.save({filename:name,data:blob});toast('Saved')}catch(e){if(e&&e.code!=='declined')toast('This view cannot save files');if(e&&(e.code==='unavailable'||e.code==='not_granted')){$('#saveBtn').hidden=true;$('#saveA3').hidden=true}}
}
$('#saveBtn').onclick=async()=>{if(!last)return;const blob=await new Promise(r=>posterCanvas().toBlob(r,'image/png'));saveBlob(blob,posterName('.png'))};
