      p.vx+=(flowV[0]*SPEED+(p.hx-p.x)*HOME-p.vx)*blend;p.vy+=(flowV[1]*SPEED+(p.hy-p.y)*HOME-5*k-p.vy)*blend;
      p.x+=p.vx*dt;p.y+=p.vy*dt;
