      p.x=p.sx+dx*e-dy/len*Math.sin(u*Math.PI)*p.amp;p.y=p.sy+dy*e+dx/len*Math.sin(u*Math.PI)*p.amp;
      if(u>=1){p.st=2;if(p.land==='paint'){introStamp(p.tx-L.pr.x,p.ty-L.pr.y,Math.max(L.pr.w,L.pr.h)*(.06+introRand()*.04));if(introRand()<.14)I.rings.push({x:p.tx,y:p.ty,t0:t,pc:p.pc,r:L.side*.06})}else{I.barLanded[p.pc]++;I.barFlying[p.pc]--}}
