  ctx.strokeStyle=faint;ctx.lineWidth=1;ctx.strokeRect(L.pr.x-.5,L.pr.y-.5,L.pr.w+1,L.pr.h+1);
  const pc=I.paint.getContext('2d');pc.setTransform(1,0,0,1,0,0);pc.globalCompositeOperation='source-over';pc.clearRect(0,0,I.paint.width,I.paint.height);
  pc.drawImage(introArt.canvas,0,0,I.paint.width,I.paint.height);pc.globalCompositeOperation='destination-in';pc.drawImage(I.mask,0,0);
