  if(ta>0){ctx.globalAlpha=fadeAll*ta;ctx.fillStyle=faint;ctx.font=`${Math.max(9,10*L.k)}px "IBM Plex Mono",monospace`;ctx.textAlign='right';ctx.textBaseline='bottom';
    ctx.fillText(`after ${introArt.title}`,L.fx+L.side,L.pr.y-5);ctx.globalAlpha=fadeAll}
  for(const r of I.rings){const a=(t-r.t0)/.6;ctx.beginPath();ctx.arc(r.x,r.y,r.r*(0.4+a*1.4),0,7);ctx.strokeStyle=`rgba(${IN_COLORS[r.pc]},${(1-a)*.7})`;ctx.lineWidth=1.2;ctx.stroke()}
