let introT0=performance.now(),introPrev=performance.now(),introVisible=true;
function introLoop(now){if(introVisible&&!SIDEMODE&&!document.hidden){const dt=clamp((now-introPrev)/1000,0,.05);introFrame((now-introT0)/1000,dt)}introPrev=now;requestAnimationFrame(introLoop)}
new IntersectionObserver(es=>{introVisible=es[0].isIntersecting}).observe($('#introCanvas'));
$('#introSound').onclick=()=>{const ac=audio(),n=IN_NOTES.length;introT0=performance.now();I=null;
  IN_NOTES.forEach((nn,i)=>tone(nn.midi,ac.currentTime+.05+i/n*IN.ph.notes,.5,.4))};

/* =========================================================
   BACKGROUND SCORE
   Behind the whole page: faint staff lines breathe, and musical notes in the twelve colors
   drift slowly upward. Notes near the pointer swirl around it and follow where it goes,
   and every note Fude plays or hears rises from where its pitch sits on the page.
   ========================================================= */
const bgCv=$('#bg'),bgCtx=bgCv.getContext('2d'),bgNoise=makeNoise(77),bgRand=mulberry32(31);
const BG={w:0,h:0,notes:[],last:performance.now(),frame:0,active:0,mx:-1e4,my:-1e4,mvx:0,mvy:0,mT:0,sig:''};
const bgSprites=new Map(),GLYPHS=['quarter','eighth','beam','half','eighth','quarter'];
// a note glyph drawn once per color and shape, then stamped
function bgSprite(pc,g){
  const key=pc+g;let c=bgSprites.get(key);if(c)return c;
  const S=2,W=44,H=56;c=document.createElement('canvas');c.width=W*S;c.height=H*S;const x=c.getContext('2d');x.scale(S,S);
  const [r,gg,b]=rgbOf(pc);x.fillStyle=x.strokeStyle=`rgb(${r},${gg},${b})`;x.lineCap='round';x.lineJoin='round';
  const head=(cx,cy,hollow)=>{x.save();x.translate(cx,cy);x.rotate(-.42);x.beginPath();x.ellipse(0,0,6.6,4.6,0,0,7);if(hollow){x.lineWidth=2.4;x.stroke()}else x.fill();x.restore()};
  const stem=(cx,cy,len)=>{x.lineWidth=1.8;x.beginPath();x.moveTo(cx+5.6,cy-1.5);x.lineTo(cx+5.6,cy-len);x.stroke()};
  if(g==='beam'){head(11,44,false);head(29,38,false);stem(11,44,26);stem(29,38,26);x.lineWidth=4.2;x.beginPath();x.moveTo(16.6,17);x.lineTo(34.6,11);x.stroke()}
  else{const cx=15,cy=42;head(cx,cy,g==='half');stem(cx,cy,30);
    if(g==='eighth'){x.lineWidth=2.2;x.beginPath();x.moveTo(cx+5.6,cy-30);x.bezierCurveTo(cx+7,cy-20,cx+17,cy-19,cx+14,cy-6);x.bezierCurveTo(cx+16,cy-15,cx+9,cy-17,cx+5.6,cy-22);x.fill()}}
  bgSprites.set(key,c);return c;
}
function bgNoteGlyph(x,y,pc,extra){return Object.assign({x,y,vx:0,vy:0,pc,g:GLYPHS[Math.floor(bgRand()*GLYPHS.length)],rot:(bgRand()-.5)*.6,rotV:(bgRand()-.5)*.25,s:.65+bgRand()*.55,ph:bgRand()*6.3,glow:0,life:-1},extra||{})}
function bgResize(){BG.w=innerWidth;BG.h=innerHeight;bgCv.width=BG.w;bgCv.height=BG.h;
  const N=MOBILE?10:20;while(BG.notes.length<N)BG.notes.push(bgNoteGlyph(bgRand()*BG.w,bgRand()*BG.h,BG.notes.length%12));}
// a note sounds: a glyph in its color rises from where its pitch sits on the page, and its kin brighten
// the wash takes on the colours of what is heard, and drifts back to its own once the music stops
const WASH={h:new Float32Array(12),el:[...document.querySelectorAll('#wash i')]};
