  const pcs=sh?sh.map((v,i)=>[v,i]).filter(x=>x[0]>0).sort((a,b)=>b[0]-a[0]).slice(0,6).map(x=>x[1]):[0,4,7];if(!pcs.length)pcs.push(0,4,7);
